<script setup>
import {ref,onUnmounted,watch,computed} from 'vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({users:Object,search:String,type:String});const {context,base,page}=useExamContext();const student=computed(()=>props.type==='student');const open=ref(false),editing=ref(null),action=ref(null),query=ref(props.search||'');let timeout;watch(query,value=>{clearTimeout(timeout);timeout=setTimeout(()=>router.get(base.value+'/users',{search:value,type:props.type},{preserveState:true,replace:true}),350);});onUnmounted(()=>clearTimeout(timeout));
const form=useForm({name:'',email:'',password:'',role:'admin',is_active:true,managed_tracks:['toeic']});const roles={admin:'Quản trị viên',teacher:'Giáo viên',student:'Thí sinh'};
function show(user=null){editing.value=user;form.clearErrors();Object.assign(form,user?{name:user.name,email:user.email,password:'',role:user.role,is_active:user.is_active,managed_tracks:user.managed_tracks||['toeic']}:{name:'',email:'',password:'',role:student.value?'student':'admin',is_active:true,managed_tracks:['toeic']});open.value=true;}
function save(){form.submit(editing.value?'put':'post',base.value+'/users'+(editing.value?'/'+editing.value.id:''),{onSuccess:()=>{open.value=false;form.reset('password');}});}
function toggle(user){action.value={url:base.value+'/users/'+user.id,method:'put',data:{name:user.name,role:user.role,is_active:!user.is_active},title:user.is_active?'Khóa tài khoản':'Mở khóa tài khoản',message:`${user.is_active?'Khóa':'Mở khóa'} tài khoản ${user.email}?`,button:'Xác nhận'};}
</script>
<template><Head :title="student?'Tài khoản thi · '+context.name:'Tài khoản quản trị'"/><AppLayout><div class="page-heading"><div><h1>{{student?'Tài khoản thi '+context.name:'Tài khoản quản trị'}}</h1><p>{{student?'Tài khoản được tạo riêng và chỉ đăng nhập vào phần thi này.':'Quản trị viên dùng chung toàn hệ thống; giáo viên được phân quyền theo phân hệ.'}}</p></div><button @click="show()">+ Thêm tài khoản</button></div><div v-if="student" class="notice">Cổng đăng nhập: <a :href="'/exam/'+context.slug+'/login'" target="_blank" rel="noopener" class="text-link">/exam/{{context.slug}}/login</a>. Sau khi tạo tài khoản, cấp đề, ngày/ca và số lượt thi.</div><div class="card"><div class="panel-title"><h2>Danh sách tài khoản</h2><Link v-if="student" :href="base+'/exam-accesses'" class="btn secondary">Cấp quyền thi →</Link></div><input v-model="query" placeholder="Tìm theo tên hoặc email…" aria-label="Tìm tài khoản"/><div class="tablewrap"><table><thead><tr><th>Họ tên</th><th>Email</th><th>{{student?'Phần thi':'Vai trò'}}</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="user in users.data" :key="user.id"><td>{{user.name}}</td><td>{{user.email}}</td><td>{{student?context.name:roles[user.role]}}<small v-if="user.role==='teacher'" class="cell-meta">{{(user.managed_tracks||['toeic']).map(slug=>page.props.modules.find(module=>module.slug===slug)?.name).join(' · ')}}</small></td><td><span class="pill" :class="{inactive:!user.is_active}">{{user.is_active?'Hoạt động':'Đã khóa'}}</span></td><td><div class="actions"><button class="secondary" @click="show(user)">Sửa / mật khẩu</button><button class="secondary" @click="toggle(user)">{{user.is_active?'Khóa':'Mở khóa'}}</button><button class="secondary" @click="action={url:base+'/users/'+user.id,title:'Xóa tài khoản',message:'Xóa tài khoản '+user.email+'? Tài khoản có lịch sử sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!users.data.length"><td colspan="5" class="empty-state">Chưa có tài khoản phù hợp.</td></tr></tbody></table></div><div class="pagination"><Link v-if="users.prev_page_url" :href="users.prev_page_url">← Trước</Link><span>Trang {{users.current_page}} / {{users.last_page}}</span><Link v-if="users.next_page_url" :href="users.next_page_url">Tiếp →</Link></div></div><AppModal :open="open" :title="editing?'Sửa tài khoản':'Thêm tài khoản'" :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><div class="field"><label for="user-name">Họ tên</label><input id="user-name" v-model="form.name" required maxlength="255"/></div><div class="field"><label for="user-email">Email đăng nhập</label><input id="user-email" v-model="form.email" type="email" required :disabled="!!editing" maxlength="255"/></div><div class="field"><label for="user-password">{{editing?'Mật khẩu mới (bỏ trống để giữ nguyên)':'Mật khẩu (ít nhất 12 ký tự)'}}</label><input id="user-password" v-model="form.password" type="password" minlength="12" maxlength="128" :required="!editing" autocomplete="new-password"/></div><div v-if="!student" class="field"><label for="user-role">Vai trò</label><select id="user-role" v-model="form.role"><option value="admin">Quản trị viên</option><option value="teacher">Giáo viên</option></select></div><div v-if="form.role==='teacher'" class="field"><label>Phân hệ được quản lý</label><div class="inline-options"><label v-for="module in page.props.modules" :key="module.slug"><input v-model="form.managed_tracks" type="checkbox" :value="module.slug"/>{{module.name}}</label></div></div><div v-if="editing" class="field"><label for="user-active">Trạng thái</label><select id="user-active" v-model="form.is_active"><option :value="true">Hoạt động</option><option :value="false">Đã khóa</option></select></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing">Lưu tài khoản</button></div></form></AppModal><ConfirmAction :action="action" @close="action=null"/></AppLayout></template>
